parser=argparse.ArgumentParser()
parser.add_argument('--pdk',required=True,type=Path)
parser.add_argument('--sram',required=True,type=Path)
parser.add_argument('--layermap',required=True,type=Path)
parser.add_argument('--out',required=True,type=Path)
a=parser.parse_args()
assert not a.out.exists(), 'Use a new output directory'
data=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
for name,text in data.items():
    if name=='ecc.toml':
        for marker,value in [('__PDK__',a.pdk),('__SRAM__',a.sram),('__LAYERS__',a.layermap)]:
            text=text.replace(marker,str(value.resolve()))
    dest=a.out/name
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(text)
print('Diagnostic only: nine real macros, no processor data paths; not functional signoff.')
